const char* password = "Luda1980";

const int LED_PIN = D4;           // GPIO2 на NodeMCU (D4) — проверь подключение
const int NUM_LEDS = 8 * 32;      // 256 светодиодов
CRGB leds[NUM_LEDS];

// API ключи (заполни своими!)
const char* ACCUWEATHER_API_KEY = "73eef4643a6cb1325f22661d0aaec437";
const char* NEWSAPI_API_KEY     = "d57c1fcd0bb54a9c9365d6cf357f1f6a";
const char* CALENDARIFIC_API_KEY = "41rLXqDg48Zux6TlCnmSw5Me891GmnbP";

// Location Key для Нижнего Новгорода (обязательно получить отдельно, см. ниже)
const char* LOCATION_KEY = "292344";

// Часовой пояс: UTC+3 для Нижнего Новгорода
const long utcOffsetSeconds = 3 * 3600;

// Интервалы обновления (в мс)
const unsigned long UPDATE_INTERVAL_WEATHER = 15 * 60 * 1000UL; // 15 минут
const unsigned long UPDATE_INTERVAL_NEWS    = 30 * 60 * 1000UL; // 30 минут
const unsigned long UPDATE_INTERVAL_HOLIDAYS = 24 * 60 * 60 * 1000UL; // 24 часа

// NTP клиент
WiFiUDP ntpUDP;
NTPClient timeClient(ntpUDP, "pool.ntp.org", utcOffsetSeconds);

// Переменные для хранения данных
String currentTemp = "--°C";
String currentCondition = "--";
String latestNews = "-- нет новостей --";
String nextHoliday = "-- нет праздников --";

// Время последнего обновления
unsigned long lastWeatherUpdate = 0;
unsigned long lastNewsUpdate = 0;
unsigned long lastHolidaysUpdate = 0;

void setup() {
  Serial.begin(115200);

  // FastLED
  FastLED.addLeds<WS2812B, LED_PIN, GRB>(leds, NUM_LEDS)
          .setCorrection(TypicalLEDStrip);
  FastLED.setBrightness(80); // подбери яркость под свою панель

  // WiFi
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println("\nWiFi connected");

  timeClient.begin();

  // Первое обновление данных
  updateWeather();
  updateNews();
  updateHolidays();
}

void loop() {
  timeClient.update();

  unsigned long now = millis();

  if (now - lastWeatherUpdate >= UPDATE_INTERVAL_WEATHER) {
    updateWeather();
    lastWeatherUpdate = now;
  }

  if (now - lastNewsUpdate >= UPDATE_INTERVAL_NEWS) {
    updateNews();
    lastNewsUpdate = now;
  }

  if (now - lastHolidaysUpdate >= UPDATE_INTERVAL_HOLIDAYS) {
    updateHolidays();
    lastHolidaysUpdate = now;
  }

  drawFrame();
  FastLED.show();
  delay(50);
}

// --- ЗАПРОСЫ API ---

void updateWeather() {
  String url = "http://dataservice.accuweather.com/currentconditions/v1/" + String(LOCATION_KEY) + "?apikey=" + ACCUWEATHER_API_KEY + "&details=false";
  HTTPClient http;
  http.begin(url);
  http.setTimeout(5000);
  int httpCode = http.GET();
  if (httpCode == 200) {
    String payload = http.getString();
    // Простой парсинг JSON без библиотек
    int tempStart = payload.indexOf("\"Temperature\":{\"Metric\":{\"Value\":") + 35;
    int tempEnd = payload.indexOf("}", tempStart);
    if (tempStart > 35 && tempEnd > tempStart) {
      currentTemp = payload.substring(tempStart, tempEnd) + "°C";
    }

    int condStart = payload.indexOf("\"WeatherText\":\"") + 16;
    int condEnd = payload.indexOf("\"", condStart);
    if (condStart > 16 && condEnd > condStart) {
      currentCondition = payload.substring(condStart, condEnd);
    }
  } else {
    Serial.printf("Weather error: %d\n", httpCode);
  }
  http.end();
}

void updateNews() {
  String url = "https://newsapi.org/v2/top-headlines?country=ru&pageSize=3&apiKey=" + NEWSAPI_API_KEY;
  HTTPClient http;
  http.begin(url);
  http.setTimeout(5000);
  int httpCode = http.GET();
  if (httpCode == 200) {
    String payload = http.getString();
    int start = payload.indexOf("\"title\":\"");
    if (start >= 0) {
      start += 9;
      int end = payload.indexOf("\"", start);
      if (end > start) {
        latestNews = payload.substring(start, end);
      }
    }
  } else {
    Serial.printf("News error: %d\n", httpCode);
  }
  http.end();
}

void updateHolidays() {
  // Получаем текущую дату из NTP
  String dateStr = getTodayDateString();
  if (dateStr.length() < 10) return;
  String year = dateStr.substring(0, 4);
  String month = dateStr.substring(5, 7);

  String url = "https://calendarific.com/api/v2/holidays?api_key=" + CALENDARIFIC_API_KEY + "&country=RU&year=" + year + "&month=" + month;
  HTTPClient http;
  http.begin(url);
  http.setTimeout(5000);
  int httpCode = http.GET();
  if (httpCode == 200) {
    String payload = http.getString();
    int idx = payload.indexOf("\"name\":\"");
    if (idx >= 0) {
      idx += 8;
      int end = payload.indexOf("\"", idx);
      if (end > idx) {
        nextHoliday = payload.substring(idx, end);
      }
    }
  } else {
    Serial.printf("Holidays error: %d\n", httpCode);
  }
  http.end();
}

String getTodayDateString() {
  // Формируем YYYY-MM-DD из NTP времени
  long currentEpoch = timeClient.getEpochTime();
  // Используем простую функцию breakTime из TimeLib (установи эту библиотеку)
  // Если TimeLib нет, можно сделать упрощённо, но лучше поставить.
  time_t t = currentEpoch;
  struct tm *ptm = gmtime(&t);
  // Корректируем на UTC+3 вручную, если NTP уже с оффсетом — тогда ptm уже верно
  // timeClient уже учитывает utcOffsetSeconds, поэтому ptm — это локальное время
  char buffer[11];
  sprintf(buffer, "%04d-%02d-%02d", ptm->tm_year + 1900, ptm->tm_mon + 1, ptm->tm_mday);
  return String(buffer);
}

